def create_vendor_beneficiaries(apps, schema_editor):
    Vendor = apps.get_model("vendors", "Vendor")
    RequisitionBeneficiary = apps.get_model(
        "requisitions",
        "RequisitionBeneficiary",
    )

    vendors = list(Vendor.objects.all().order_by("id"))

    beneficiaries = []

    for vendor in vendors:
        beneficiaries.append(
            RequisitionBeneficiary(
                institution_id=vendor.institution_id,
                name=vendor.vendor_name,
                email=vendor.email,
                # phone_number=vendor.phone_number,
                account_number=vendor.phone_number,
            )
        )

    created_beneficiaries = RequisitionBeneficiary.objects.bulk_create(
        beneficiaries,
        batch_size=1000,
    )

    for vendor, beneficiary in zip(vendors, created_beneficiaries):
        vendor.requisition_beneficiary_id = beneficiary.id

    Vendor.objects.bulk_update(
        vendors,
        ["requisition_beneficiary_id"],
        batch_size=1000,
    )


